import sharp from 'sharp';
import fs from 'fs-extra';
import path from 'path';
import { ORIGINAL_DIR, SMALL_DIR } from './config';

export interface ProcessedImage {
    fileNameOriginal: string;
    fileNameSmall: string;
}

export const processImage = async (file: Express.Multer.File): Promise<ProcessedImage> => {
    await fs.ensureDir(ORIGINAL_DIR);
    await fs.ensureDir(SMALL_DIR);

    // file.filename was generated by multer's storage config (upload.ts) as a
    // random uuid + validated extension
    const timestamp = Date.now();
    const originalName = `${timestamp}-${file.filename}`;
    // La vignette est encodée en WebP plutôt qu'en JPEG
    const smallName = `${timestamp}-small-${path.parse(file.filename).name}.webp`;

    const originalPath = path.join(ORIGINAL_DIR, originalName);
    const smallPath = path.join(SMALL_DIR, smallName);

    try {
        // Save original.
        await fs.move(file.path, originalPath);

        // Generate and save small version.
        await sharp(originalPath)
            .rotate()
            .resize(400, 400, { fit: 'outside' })
            .webp({ quality: 80 })
            .toFile(smallPath);
    } catch (err) {
        await restoreFailedImage(file, originalName, smallName);
        throw err;
    }

    return {
        fileNameOriginal: originalName,
        fileNameSmall: smallName
    };
};

// En cas d'échec, le fichier reste disponible dans temp pour inspection,
// mais aucun fichier traité ne reste dans original ou small.
export async function restoreFailedImage(
    file: Express.Multer.File,
    fileNameOriginal: string,
    fileNameSmall: string
): Promise<void> {
    const originalPath = path.join(ORIGINAL_DIR, fileNameOriginal);
    const smallPath = path.join(SMALL_DIR, fileNameSmall);

    if (await fs.pathExists(originalPath) && !(await fs.pathExists(file.path))) {
        await fs.move(originalPath, file.path);
    }
    await fs.remove(originalPath);
    await fs.remove(smallPath);
}

// Dimensions de l'aperçu de partage : le format 1,91:1 attendu par Open
// Graph, et assez grand pour que les messageries affichent la grande
// vignette plutôt qu'une pastille.
export const SHARE_IMAGE_WIDTH = 1200;
export const SHARE_IMAGE_HEIGHT = 630;

/**
 * L'aperçu de partage d'une photo : un JPEG recadré au format ci-dessus.
 *
 * Produit à la volée plutôt que stocké : un lecteur de lien ne le demande
 * qu'une fois et le garde ensuite en cache. La vignette du site ne pouvait
 * pas servir — elle est en WebP, que plusieurs clients (dont WhatsApp)
 * n'affichent pas dans un aperçu, et trop petite pour la grande vignette.
 */
export async function renderShareImage(sourcePath: string): Promise<Buffer> {
    return sharp(sourcePath)
        .rotate()
        .resize(SHARE_IMAGE_WIDTH, SHARE_IMAGE_HEIGHT, {
            fit: 'cover',
            // Une photo sur deux est prise en portrait : le cadrage en perd
            // alors les deux tiers en hauteur. `attention` laisse sharp
            // choisir la bande à garder d'après les contrastes et les
            // couleurs vives, ce qui retient le panneau plutôt que le ciel.
            position: sharp.strategy.attention,
        })
        .jpeg({ quality: 80 })
        .toBuffer();
}
